/** The FF.AI app icon (public/icons/logo-mark.png, generated by scripts/generate_icons.py). */
export function BrandMark({ size = 32 }: { size?: number }) {
  return (
    // A plain <img>: the 128 px file is already optimised and must not wait for the image loader.
    // eslint-disable-next-line @next/next/no-img-element
    <img src="/icons/logo-mark.png" width={size} height={size} alt="" aria-hidden="true" className="brand-mark" decoding="async" />
  );
}
